INSERT INTO `news_article` (`id`, `media_name`, `author`, `title`, `content`, `publish_time`, `publish_date_time`, `url`, `read_count`, `comment_count`, `share_count`, `source_keyword`) VALUES
(1, '科技传真', '本报记者', '星耀科技回应X-Phone 15发热问题：将推送优化版本', '分享一下：针对近期用户反馈，星耀科技今日发布说明称，已成立专项小组跟进，后续将通过系统更新优化功耗调度策略，并为有需要的用户提供检测服务。公司同时表示，产品各项指标均符合相关标准。', 1791827841, '2026-10-13 01:57:21+08:00', 'https://news.example-portal.com/新闻门户/1.html', '597135', '56', '7249', '星耀XPhone15'),
(2, '科技传真', '本报记者', 'X-Phone 15 发热争议持续，客服称属正常现象引用户不满', '近日，多位用户在社交平台反映星耀科技新机 X-Phone 15 存在发热与续航问题。有用户称联系客服后被告知「属于正常现象」，该回应在网上引发进一步讨论。截至发稿，星耀科技尚未发布正式说明。 #手机发热#', 1791820922, '2026-10-13 00:02:02+08:00', 'https://news.example-portal.com/新闻门户/2.html', '557380', '25', '8034', '星耀XPhone15'),
(3, '科技传真', '记者 王', 'X-Phone 15 发热争议持续，客服称属正常现象引用户不满', '星耀科技 X-Phone 15 上市一周，围绕机身发热的讨论持续发酵。第三方测评机构公布的实测数据显示，该机型满载温度较上一代有所上升。业内人士认为，散热卖点与实际体验的落差是本次争议的核心。 大家怎么看？ #数码#', 1791816790, '2026-10-12 22:53:10+08:00', 'https://news.example-portal.com/新闻门户/3.html', '265068', '98', '7921', '星耀XPhone15'),
